const modelContext=document.modelContext;
if(modelContext?.registerTool){
  const lifecycle=new AbortController();
  const tools=[
    {name:'stage_music_list_setlists',title:'Listar repertórios',description:'Lê os repertórios da conta atual no Stage Music.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>({setlists:(await api.mySetlists()).map(s=>({id:s.id,name:s.name,items:s.items.length}))})},
    {name:'stage_music_create_setlist',title:'Criar repertório',description:'Cria um repertório vazio e o abre na interface. Não inicia nem publica uma Sala Live.',inputSchema:{type:'object',properties:{name:{type:'string',minLength:1,maxLength:120}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||typeof input.name!=='string'||!input.name.trim()||input.name.length>120||Object.keys(input).some(k=>k!=='name'))throw new Error('Informe apenas um nome de até 120 caracteres.');const s=await api.save('setlists',{name:input.name.trim(),createdBy:api.me(),organizationId:api.state.organization?.id||'',eventName:'',eventDate:'',note:'',items:[]});history.replaceState(null,'','#/setlist/'+s.id);await render();return {id:s.id,name:s.name,items:0};}}
  ];
  for(const tool of tools)try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
